/* 内置的 wasm（base64） —— file:// 下 fetch 拿不到本地文件，只能直接喂字节。
   生成脚本 .tmpchk/make_wasm_inline.py，别手改。惰性解码：用到才解，不拖慢首屏。 */
(function(){
  var B64 = {"88cbdbdfffc17eaa.wasm":"","dc6fb76aeb75e986.wasm":""};
  var cache = {};
  function decode(k){
    if(cache[k]) return cache[k];
    var bin = atob(B64[k]), n = bin.length, u = new Uint8Array(n), i;
    for(i = 0; i < n; i++) u[i] = bin.charCodeAt(i);
    cache[k] = u;
    return u;
  }
  window.__YY_WASM__ = B64;
  var orig = window.fetch ? window.fetch.bind(window) : null;
  window.fetch = function(input, init){
    try{
      var u = (typeof input === 'string') ? input
            : (input && input.url) ? input.url : String(input);
      var m = /(?:^|[\\/])([A-Za-z0-9_-]+\.wasm)(?:\?[^#]*)?$/.exec(u);
      if(m && B64[m[1]]){
        return Promise.resolve(new Response(decode(m[1]), {
          status: 200, statusText: 'OK',
          headers: { 'Content-Type': 'application/wasm' }
        }));
      }
    }catch(e){}
    if(orig) return orig(input, init);
    return Promise.reject(new TypeError('fetch unavailable'));
  };
})();
